main {
  padding-top: var(--nav-height);
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.container--narrow {
  max-width: var(--content-width);
}

/* --- Section Spacing --- */
.section {
  padding: var(--space-3xl) 0;
}

.section--lg {
  padding: 10rem 0;
}

/* --- Typography --- */
.heading-xl {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 5.5rem);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.03em;
}

.heading-lg {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 4vw, 3.5rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.heading-md {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 2.5vw, 2rem);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.01em;
}

.heading-sm {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  font-weight: 600;
  line-height: 1.3;
}

.label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.body-text {
  font-size: 1.05rem;
  line-height: 1.7;
  color: var(--text);
}

.body-text--large {
  font-size: clamp(1.1rem, 1.5vw, 1.3rem);
  line-height: 1.75;
}

/* --- Media Showcase (Triptych) --- */
.media-showcase {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
  width: 100%;
}

.media-showcase__item {
  aspect-ratio: 3 / 4;
  border-radius: 4px;
  overflow: hidden;
}

.media-showcase__item--terracotta {
  background-color: var(--accent-terracotta);
}

.media-showcase__item--sage {
  background-color: var(--accent-sage);
}

.media-showcase__item--sand {
  background-color: var(--accent-sand);
}

/* --- Client Marquee --- */
.marquee-section {
  padding: var(--space-2xl) 0;
  overflow: hidden;
  border-top: 1px solid rgba(26, 26, 26, 0.08);
  border-bottom: 1px solid rgba(26, 26, 26, 0.08);
}

.marquee-row {
  display: flex;
  width: max-content;
  gap: 0;
}

.marquee-row--left {
  animation: marquee-left 40s linear infinite;
}

.marquee-row--right {
  animation: marquee-right 40s linear infinite;
}

.marquee-row:nth-child(2) {
  margin: 0.75rem 0;
}

.marquee-item {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 2vw, 1.75rem);
  font-weight: 500;
  white-space: nowrap;
  padding: 0 1.5rem;
  color: var(--text);
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.marquee-item::after {
  content: '◦';
  color: var(--text-light);
  font-size: 0.8em;
}

.marquee-item:last-child::after {
  display: none;
}

@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

@media (prefers-reduced-motion: reduce) {
  .marquee-row--left,
  .marquee-row--right {
    animation: none;
    flex-wrap: wrap;
    width: auto;
  }
}

/* --- About Section --- */
.about-section {
  padding: var(--space-3xl) 0;
}

.about-section .label {
  margin-bottom: var(--space-md);
}

.about-section .body-text {
  max-width: 640px;
}

.about-section .body-text + .body-text {
  margin-top: var(--space-md);
}

/* --- Founder Letter (neweno.html) --- */
.founder-letter {
  padding: var(--space-3xl) 0;
}

.founder-letter .heading-xl {
  margin-bottom: var(--space-2xl);
}

.founder-letter .body-text--large {
  max-width: var(--content-width);
}

.founder-letter .body-text--large + .body-text--large {
  margin-top: var(--space-lg);
}

.letter-sign-off {
  margin-top: var(--space-2xl);
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 600;
  font-style: italic;
}

/* --- Philosophy Section --- */
.philosophy-section {
  padding: var(--space-3xl) 0;
}

.philosophy-section .heading-xl {
  margin-bottom: var(--space-lg);
}

.philosophy-section .body-text--large {
  max-width: 640px;
}

/* --- Divider --- */
.divider {
  width: 60px;
  height: 2px;
  background: var(--text);
  opacity: 0.2;
  margin: var(--space-3xl) auto;
}

/* --- Service Details --- */
.services-list {
  display: grid;
  gap: var(--space-2xl);
  max-width: 900px;
}

.service-item {
  padding-bottom: var(--space-2xl);
  border-bottom: 1px solid rgba(26, 26, 26, 0.08);
}

.service-item:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.service-item h3 {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 2vw, 1.5rem);
  font-weight: 600;
  margin-bottom: var(--space-sm);
}

.service-item h3 span {
  color: var(--text-muted);
  font-weight: 400;
}

.service-item .body-text {
  max-width: 600px;
}

/* --- Clients Grid --- */
.clients-heading {
  padding: var(--space-3xl) 0 var(--space-xl);
}

.clients-heading .heading-lg span {
  color: var(--text-muted);
  font-weight: 400;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2px;
  padding-bottom: var(--space-3xl);
}

.client-card {
  padding: var(--space-lg);
  border: 1px solid rgba(26, 26, 26, 0.06);
  background: transparent;
  transition: background var(--duration-fast) var(--ease-out);
}

.client-card:hover {
  background: rgba(26, 26, 26, 0.02);
}

.client-card h3 {
  font-family: var(--font-serif);
  font-size: 1.15rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.client-card p {
  font-size: 0.9rem;
  line-height: 1.6;
  color: var(--text-muted);
}

.client-card--more {
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-sans);
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
}

/* --- Contact Page --- */
.contact-hero {
  min-height: calc(100vh - var(--nav-height));
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  padding: var(--space-3xl) 0;
}

.contact-hero .heading-xl {
  font-size: clamp(4rem, 14vw, 12rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 0.9;
  margin-bottom: var(--space-2xl);
}

.contact-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.contact-links a {
  font-family: var(--font-sans);
  font-size: 1.1rem;
  font-weight: 400;
  color: var(--text-muted);
  transition: color var(--duration-fast) var(--ease-out);
  cursor: pointer;
}

.contact-links a:hover {
  color: var(--text);
}

/* --- Footer --- */
.site-footer {
  padding: var(--space-xl) var(--space-lg);
  border-top: 1px solid rgba(26, 26, 26, 0.08);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.site-footer span {
  font-size: 0.8rem;
  color: var(--text-light);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  :root {
    --space-lg: 1.5rem;
    --space-2xl: 4rem;
    --space-3xl: 5rem;
  }

  .nav-links {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .media-showcase {
    grid-template-columns: 1fr;
    gap: 0.5rem;
  }

  .media-showcase__item {
    aspect-ratio: 16 / 9;
  }

  .clients-grid {
    grid-template-columns: 1fr;
  }

  .contact-hero .heading-xl {
    font-size: clamp(3rem, 18vw, 7rem);
  }

  .site-footer {
    flex-direction: column;
    gap: var(--space-sm);
    text-align: center;
  }
}

@media (max-width: 480px) {
  .site-header {
    padding: 0 var(--space-md);
  }

  .site-header::after {
    left: var(--space-md);
    right: var(--space-md);
  }

  .container {
    padding: 0 var(--space-md);
  }

  .mobile-overlay a {
    font-size: 1.5rem;
  }
}

